test "t0" {
    assert (rc('ACTGACTG') == 'CAGTCAGT');;
}

test "t1" {
    assert (rc('atcgatcg') == 'cgatcgat');;
}

test "t2" {
    assert (rc(('G' * 1000000)) == ('C' * 1000000));;
}

test "t3" {
    assert (rc(('T' * 1000000)) == ('A' * 1000000));;
}

test "t4" {
    assert (rc(('A' * 1000000)) == ('T' * 1000000));;
}
